"""Oracle audit (2026-11-24): runs every simulation row of tests/usb20/testlist.csv (first seed) once per negative control of the
testbench and reports which scenarios still PASS although the DUT side was broken on purpose:

  nc_dead    the DUT stays in reset                         -> every scenario must FAIL
  nc_silent  no packet of the DUT reaches the checks        -> every scenario that expects a USB packet of the DUT must FAIL
  nc_data    one payload bit of each DUT data packet flipped, CRC16 recomputed -> must FAIL when the DUT sent a data packet
  nc_mem     one bit of each AXI write beat flipped in the memory model        -> must FAIL when the DUT wrote memory

A PASS is reported as GAP only when the control had an effect in that run (the testbench prints the number of DUT packets, of
flipped data packets and of flipped write beats); a PASS without effect is NOT APPLICABLE. Runs use +stop1 (end at the first
failed check) and are named t_nc_<control>_<test>; reports and the vplan ignore them.
    python env/scripts/oracle_audit.py [control ...] [--only test ...]     (from the verification folder)
Output: sim/oracle_audit.md and sim/oracle_audit.csv"""
import csv
import os
import re
import subprocess
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import vpaths as P  # noqa: E402

CONTROLS = ['nc_dead', 'nc_silent', 'nc_data', 'nc_mem']
SKIP_SRC = ('gen_host_edge.py:imax', 'gen_host_edge.py:sof')        # 10-minute runs that only count SOF packets


def main():
    a = sys.argv[1:]
    only = a[a.index('--only') + 1:] if '--only' in a else []
    ctls = [x for x in a if x in CONTROLS] or CONTROLS
    rows = [r for r in csv.DictReader(open(P.TESTLIST)) if r['kind'] == 'sim' and r['tier'] != 'open' and r['source'] != '-'
            and not r['source'].startswith(SKIP_SRC) and (not only or r['test'] in only)]
    out = []
    os.chdir(P.V)
    for r in rows:
        seed = r['seeds'].split()[0] if r['seeds'].strip() else '1'
        src = r['source'].split(':')
        g = subprocess.run([sys.executable, src[0], seed] + src[1:], cwd=P.TESTS, capture_output=True, text=True)
        if g.returncode != 0:
            out.append((r['test'], r['source'], r['target'], '-', 'GENERATOR FAILED', '', ''))
            continue
        ops = 'tests/' + g.stdout.strip().split('\n')[-1]
        for c in ctls:
            p = subprocess.run([sys.executable, 'env/scripts/run.py', 'sim', 't_nc_%s_%s' % (c[3:], r['test'][2:]), r['target'], ops,
                                '+seed=%s' % seed, '+' + c, '+stop1'] + r['extra'].split(), capture_output=True, text=True)
            first = (p.stdout.strip().split('\n') or [''])[0]
            rid = first.split()[0] if first else ''
            log = os.path.join(P.run_dir(rid), 'sim.log') if rid else ''
            txt = open(log, errors='ignore').read() if log and os.path.exists(log) else ''
            m = re.search(r'NC dead=\d+ silent=\d+ data=\d+ mem=\d+ dut_packets=(\d+) data_flips=(\d+) mem_flips=(\d+)', txt)
            pk, df, mf = (int(x) for x in m.groups()) if m else (0, 0, 0)
            verdict = 'PASS' if first.endswith('PASS') else 'FAIL'
            effect = {'nc_dead': True, 'nc_silent': pk > 0, 'nc_data': df > 0, 'nc_mem': mf > 0}[c]
            cls = ('GAP' if effect else 'NOT APPLICABLE') if verdict == 'PASS' else 'caught'
            fl = re.findall(r'^FAIL.*$', txt, re.M)
            out.append((r['test'], r['source'], r['target'], c, cls, rid, (fl[0][:140] if fl else '').replace('|', '/')))
            print('%-24s %-34s %-10s %-15s %s' % (r['test'], r['source'][:34], c, cls, rid), flush=True)
    with open(os.path.join(P.SIMOUT, 'oracle_audit.csv'), 'w', newline='') as f:
        w = csv.writer(f)
        w.writerow(['test', 'source', 'build', 'control', 'result', 'run', 'first failure'])
        w.writerows(out)
    gaps = [o for o in out if o[4] == 'GAP']
    md = ['# Oracle audit (negative controls)', '', 'Generated by `env/scripts/oracle_audit.py`. GAP = the scenario passed although the control '
          'broke the DUT side and had an effect in the run; caught = the scenario failed; NOT APPLICABLE = the control had no effect.', '',
          '%d runs, %d GAP.' % (len(out), len(gaps)), '', '| Test | Scenario | Build | Control | Result | Run | First failure |', '|---|---|---|---|---|---|---|']
    md += ['| %s |' % ' | '.join(str(x) for x in o) for o in out]
    open(os.path.join(P.SIMOUT, 'oracle_audit.md'), 'w').write('\n'.join(md) + '\n')
    print('runs %d, GAP %d' % (len(out), len(gaps)))
    return 0


if __name__ == '__main__':
    sys.exit(main())
